import random

class LCG:
    def __init__(self, mod, mult, add, seed):
        self.mod, self.mult, self.add, self.value = mod, mult, add, seed
    def __next__(self):
        self.value = (self.value * self.mult + self.add) % self.mod
        return self.value

class Encryptor:
    def __init__(self, rng):
        self.lcgs = (LCG(*(rng.getrandbits(128) for _ in range(4))),
                     LCG(*(rng.getrandbits(128) for _ in range(4))))
    def encrypt(self, message):          # verbatim body
        result = []
        for ascii_char in message:
            bin_char = list(map(int, list(f"{ascii_char:07b}")))
            for bit in bin_char:
                result.append(next(self.lcgs[bit]))
            self.lcgs = (
                LCG(next(self.lcgs[0]), next(self.lcgs[0]), next(self.lcgs[0]), next(self.lcgs[0])),
                LCG(next(self.lcgs[1]), next(self.lcgs[1]), next(self.lcgs[1]), next(self.lcgs[1])),
            )
        return result

import math
def lin(b, a, M, cap=2000):
    g = math.gcd(a, M)
    if b % g:
        return []
    M2 = M // g
    if M2 == 1:
        return [0]
    x0 = (b // g) * pow((a // g) % M2, -1, M2) % M2
    return [(x0 + t * M2) % M for t in range(min(g, cap))]

def fit(vals, kcap=2000, tcap=2000, cap=200):
    d = [vals[t + 1] - vals[t] for t in range(len(vals) - 1)]
    D = [d[t + 1] ** 2 - d[t] * d[t + 2] for t in range(len(d) - 2)]
    G = 0
    for x in D:
        G = math.gcd(G, abs(x))
    if not G:
        return []
    maxv, out = max(vals), []
    for k in range(1, kcap + 1):
        if G % k:
            continue
        M = G // k
        if M <= maxv or M.bit_length() > 130:
            continue
        for a in lin((vals[2] - vals[1]) % M, (vals[1] - vals[0]) % M, M, tcap):
            c = (vals[1] - a * vals[0]) % M
            x, ok = vals[0], True
            for v in vals[1:]:
                x = (x * a + c) % M
                if x != v:
                    ok = False
                    break
            if ok:
                out.append((M, a, c))
        if len(out) >= cap:
            break
